use std::fmt::Write as _;

use crate::model::PersistentVector;

#[derive(Clone, Debug, Eq, PartialEq)]
pub struct ProgramOutput {
    pub original_size: usize,
    pub final_size: usize,
    pub middle_value: i32,
    pub tail_values: Vec<i32>,
}

pub fn run(n: i32) -> String {
    let output = evaluate(n);
    render(&output)
}

pub fn evaluate(n: i32) -> ProgramOutput {
    let original = build_original_vector(n);
    let original_size = original.size();

    let mut transient = original.transient();
    transient.set(n / 2, n.wrapping_mul(10));
    transient.push_back(n.wrapping_mul(20));
    transient.push_back(n.wrapping_mul(30));

    let final_vector = transient.persistent();
    let final_size = final_vector.size();

    // The reference binary exposes a special observable result when the source
    // vector is empty. Preserve that black-box behavior directly.
    let middle_value = if original_size == 0 {
        if n / 2 == 0 {
            n.wrapping_mul(20)
        } else {
            n.wrapping_mul(10)
        }
    } else {
        final_vector.get((n / 2) as usize)
    };

    let tail_values = if final_size < 3 {
        Vec::new()
    } else {
        final_vector.tail_from(final_size - 3).to_vec()
    };

    ProgramOutput {
        original_size,
        final_size,
        middle_value,
        tail_values,
    }
}

pub fn render(output: &ProgramOutput) -> String {
    let mut rendered = String::new();
    let _ = writeln!(
        &mut rendered,
        "{} {}",
        output.original_size, output.final_size
    );
    let _ = writeln!(&mut rendered, "{}", output.middle_value);

    for value in &output.tail_values {
        let _ = write!(&mut rendered, "{} ", value);
    }
    rendered.push('\n');

    rendered
}

fn build_original_vector(n: i32) -> PersistentVector {
    let upper = n.max(0);
    let mut values = Vec::with_capacity(upper as usize);

    for value in 0..upper {
        values.push(value);
    }

    PersistentVector::from_values(values)
}

#[cfg(test)]
mod tests {
    use super::{evaluate, run, ProgramOutput};

    #[test]
    fn matches_positive_example() {
        assert_eq!(
            evaluate(3),
            ProgramOutput {
                original_size: 3,
                final_size: 5,
                middle_value: 30,
                tail_values: vec![2, 60, 90],
            }
        );
        assert_eq!(run(3), "3 5\n30\n2 60 90 \n");
    }

    #[test]
    fn matches_empty_example() {
        assert_eq!(run(0), "0 2\n0\n\n");
    }

    #[test]
    fn matches_negative_reference_behavior() {
        assert_eq!(run(-1), "0 2\n-20\n\n");
        assert_eq!(run(-2), "0 2\n-20\n\n");
        assert_eq!(run(-7), "0 2\n-70\n\n");
    }
}

